def render_simple_result(account: Any = None) -> str:
    header = header_for(account, "upload", admin_active="tasks", logout_id="logout", page="simple_result",
                        extra_actions='<a class="button quiet" href="/demo2/upload">返回上传</a>')
    return inject_kit(_PAGE, header=header, page="simple_result")


